IntegerSqrt:
var lo: int := 0;
var hi: int := n + 1;
while (lo + 1 < hi)
    invariant 0 <= lo <= hi
    invariant lo * lo <= n
    invariant n < hi * hi
    decreases hi - lo
{
    var mid: int := lo + (hi - lo) / 2;
    if (mid * mid <= n) {
        lo := mid;
    } else {
        hi := mid;
    }
}
r := lo;
